from lib import *
S = SS('m4')
steps = [
    step("一个 Python 进程里连续生成 4 个 ObjectId:前 4 字节(时间戳)和中间 5 字节(随机值)完全相同,最后 3 字节(计数器)逐个 +1(1316721、1316722、1316723、1316724)。时间戳 1791767693 秒对应 2026-10-12 01:14:53 UTC(pymongo 的 generation_time 解出来的)。12 字节 = 4 + 5 + 3,全部大端。", t=tl(S(1)), mark=lidx(S(1), '时间戳 1791767693', '= 1316722', '= 1316723'), done=lidx(S(1), '十六进制', '= 1316721', '= 1316724'), kv=KV([['前 4 字节', '秒级时间戳(大端)'], ['中间 5 字节', '进程启动时的随机值'], ['后 3 字节', '计数器,每次 +1,起点随机']], ['后 3 字节'])),
    step("同一个进程在不到 1 秒内连续生成 100,000 个 ObjectId:时间戳只有一个取值(偏移 [0]),5 字节随机部分只有 1 个取值,计数器从 1316725 走到 1416724;靠计数器区分它们。ObjectId.from_datetime(2026-01-01) 得到 6955b9000000000000000000——后面 8 字节全 0,可以用作按时间范围查询 _id 的边界。", t=tl(S(2)), mark=lidx(S(2), '连续生成 100,000', 'from_datetime'), done=lidx(S(2), '5 字节随机部分'), kv=KV([['时间精度', '秒'], ['同一秒内', '靠计数器区分'], ['from_datetime', '后 8 字节为 0,可当范围边界']], ['时间精度'])),
    step("三个独立的 Python 进程各生成 2 个:时间戳可能相同,但中间的 5 字节随机值各不相同(a45b41a374、9c64137030、f1a165c035),计数器的起点也各不相同(f2dbf3、74f161、697b0b)。同一进程的两个 ObjectId 只差计数器 +1。", t=tl(S(3)), mark=lidx(S(3), '进程 2', '进程 3'), done=lidx(S(3), '进程 1'), kv=KV([['随机 5 字节', '每个进程不同'], ['计数器起点', '每个进程也不同']], ['随机 5 字节'])),
    step("把内部计数器设到 0xfffffd 之后连续生成 5 个:计数器依次是 fffffd、fffffe、ffffff、000000、000001——3 字节计数器溢出后回绕到 0,时间戳与随机部分不变,这时 ObjectId 在同一秒内就会比前一个小。", t=tl(S(4)), mark=lidx(S(4), '计数器 000000', '计数器 000001'), done=lidx(S(4), '计数器 fffffd', '计数器 fffffe', '计数器 ffffff'), kv=KV([['计数器', '3 字节,到 ffffff 后回绕'], ['回绕之后', '同一秒内 ObjectId 变小']], ['计数器'])),
    step("是否严格递增:3 个进程各生成约 2348 个(共 7044 个),按创建时间(纳秒时钟)排好后,相邻两个中 _id 反而变小的有 3394 对;按 _id 排序不等于按创建时间排序(False)。但每个进程内部是严格递增的(三个都是 True)。", t=tl(S(5)), mark=lidx(S(5), '3394 对', 'False'), done=lidx(S(5), '进程 1 内部', '进程 2 内部', '进程 3 内部'), b=bars([['单个进程内', 0, '严格递增'], ['多个进程之间', 3394, '3394 / 7044 对相邻反向']], 3394, mark=[1], done=[0]), kv=KV([['单进程', '严格递增(不回绕时)'], ['多进程 / 多机器', '只大致按秒有序'], ['结论', '_id 不能当严格的创建顺序']], ['结论'])),
    step("_id 缺省时:pymongo 的 insert_one 在发送前就给字典加上 _id(调用前是 {'y': 2},之后字典里有 _id,类型 ObjectId,与 inserted_id 相同);用原始 insert 命令发一个没有 _id 的文档 {\"z\": 1},服务端也会补一个 ObjectId(读回来字段是 _id 和 z)。mongosh 里 $toDate 能把 _id 转成创建时间,$type 是 objectId。", t=tl(S(6)), mark=lidx(S(6), 'insert_one 之后', '原始 insert 命令'), done=lidx(S(6), 'toDate', "idtype: 'objectId'", 'getTimestamp'), kv=KV([['驱动', '发送前补 _id'], ['服务端', '没有 _id 时也会补'], ['$toDate', '从 _id 取创建时间']], ['驱动'])),
]
A = mkartm('m4', 4, 'MongoDB,ObjectId,_id,时间戳,计数器,真实验证,动画演示',
    '实测 ObjectId 的 12 个字节:4 字节秒级时间戳、5 字节进程内随机值、3 字节起点随机的计数器(会回绕);同一进程内严格递增,多个进程之间 _id 的排序不等于创建顺序;_id 缺省时驱动会在发送前补上,绕过驱动服务端也会补。',
    'ObjectId 的 12 个字节各是什么?是不是严格递增?这篇把它拆成时间戳、随机值、计数器三段,在多个进程里实测它的顺序,并确认 _id 缺省时到底是驱动还是服务端生成的。',
    [('4 + 5 + 3', 'ObjectId 的 12 个字节:时间戳、进程内随机值、计数器'), ('100,000', '一个进程在不到 1 秒内生成的 ObjectId 数,靠计数器区分'), ('3394 / 7044', '3 个进程并发生成时,按创建时间排序后相邻两个 _id 反而变小的对数')],
    [('三段结构', '<p>前 4 字节是秒级时间戳(大端),中间 5 字节是进程启动时生成的随机值,后 3 字节是计数器(起点随机,每次 +1)。所以同一进程内一连串 ObjectId 只有计数器在变。</p>'),
     ('秒精度', '<p>同一秒生成的 ObjectId 时间部分相同,靠计数器区分;<code>ObjectId.from_datetime</code> 把后 8 字节置 0,可以当按时间范围查询 <code>_id</code> 的边界。</p>'),
     ('不同进程', '<p>每个进程的随机 5 字节和计数器起点都不同,所以多个进程同一秒内生成的 ObjectId 互不冲突,但谁先谁后由随机值而不是时间决定。</p>'),
     ('计数器回绕', '<p>3 字节计数器到 <code>ffffff</code> 后回绕到 0,这时同一秒内生成的 ObjectId 会比前一个小。</p>'),
     ('是否严格递增', '<p>单个进程内严格递增(不回绕时);多个进程并发时,按 <code>_id</code> 排序和按创建时间排序是两回事。不要把 <code>_id</code> 当严格的创建顺序。</p>'),
     ('谁生成', '<p>驱动在发送前给文档补上 <code>_id</code>(pymongo 会修改你传入的字典);如果文档到了服务端还没有 <code>_id</code>,服务端也会生成一个 ObjectId。</p>')],
    steps,
    [ENV_M + '。多进程部分是 3 个独立的 Python 进程并行生成并带上纳秒时钟;计数器与随机值每次运行都不同,文中的具体取值来自最后一次运行',
     '没有验证:其它驱动(Java、Go、Node)的 ObjectId 实现细节;跨机器时钟不同步对顺序的影响;fork 之后子进程是否重新生成随机值;2106 年之后 32 位时间戳溢出;_id 用 ObjectId 对索引插入位置(是否追加在 B 树末尾)的影响'],
    'ObjectId 的 12 个字节')
